var devUrl="https://localhost:44323",prodUrl="https://www.moi.gov.kw",serverUrl=prodUrl;getGetRefNumAPIUrl=()=>serverUrl+"/mfservices/nationalnumber/";QAGetNationalNumber=(n,t,i)=>{$.ajax({url:getGetRefNumAPIUrl()+"get-national-number/"+n+"/"+t+"/"+i,type:"GET",contentType:"application/json;charset=utf-8",success:function(n){$("#btnGetRefNum").attr("disabled",!1);$("#btnMGetRefNum").attr("disabled",!1);QAShowRefNumResult(n);$("#QARNWorkingOnIt").addClass("d-none");$("#MQARNWorkingOnIt").addClass("d-none")},error:function(n){$("#QARNWorkingOnIt").addClass("d-none");$("#MQARNWorkingOnIt").addClass("d-none");console.log(n);$("#btnGetRefNum").attr("disabled",!1);$("#btnMGetRefNum").attr("disabled",!1);var t=$.parseJSON(n.responseText);console.log(t.errorMessage)}})};